create table if not exists employees (id uuid primary key default gen_random_uuid(), employee_number text unique not null, first_name text not null, middle_name text, last_name text not null, email text, phone text, address text, birth_date date, hire_date date not null, employment_status text not null, employment_type text, position text, department text, salary_grade_id uuid, status text not null default 'Active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
